s = p.read_text()
s = s.replace('if cursor >= end_utc:', 'if cursor > end_utc:')
s = s.replace('if start_utc <= record.open_time < end_utc:\n                    candles_by_time[record.open_time] = candle', 'candles_by_time[record.open_time] = candle')
